//
//  GenreParsingTests.swift
//  QQPlayerTests
//
//  E1-S3：genre 全链路（解析器读 genre → DB 落库）测试。
//  - 解析器从带 genre 标签的音频读流派：MP3 ID3 TCON / M4A iTunes ©gen /
//    FLAC VORBIS_COMMENT GENRE（对齐 web extract_tags：tcon/©gen/genre）
//  - 无 genre 文件 → nil；空串/纯空白 → nil（AudioMetadata.genre 为 String?）
//  - Track DB 往返：新库（CREATE 含 genre 列）upsert → 读回一致
//  - 老库迁移：track 表无 genre 列 → addTrackGenreColumnIfNeeded 补列（幂等）
//
//  fixture：ffmpeg 合成 0.3s 静音（sine 440Hz）；genre 版本带 genre="Rock"，
//  mutagen 交叉验证 TCON/©gen/GENRE 均可读，base64 内嵌（与 E1-S1 同法）。
//

import Foundation
import GRDB
import Testing

@testable import QQPlayer

struct GenreParsingTests {
    // MARK: - Fixtures（base64 内嵌，0.3s 静音无版权）

    private static let mp3RockBase64 = ""
    private static let flacRockBase64 = ""
    private static let m4aRockBase64 = ""
    private static let mp3NoGenreBase64 = ""
    private static let flacNoGenreBase64 = ""
    private static let m4aNoGenreBase64 = ""

    private func writeFixture(named name: String, base64: String) throws -> URL {
        let dir = FileManager.default.temporaryDirectory
            .appendingPathComponent("GenreParsingTests-\(UUID().uuidString)")
        try FileManager.default.createDirectory(at: dir, withIntermediateDirectories: true)
        let url = dir.appendingPathComponent(name)
        try Data(base64Encoded: base64)!.write(to: url)
        return url
    }

    // MARK: - 解析器读 genre

    @Test("MP3：ID3 TCON 帧 → genre = Rock")
    func mp3GenreParsed() async throws {
        let url = try writeFixture(named: "genre-rock.mp3", base64: Self.mp3RockBase64)
        defer { try? FileManager.default.removeItem(at: url.deletingLastPathComponent()) }
        let metadata = try await AudioMetadataParser.parseMetadata(from: url)
        #expect(metadata.genre == "Rock")
    }

    @Test("FLAC：VORBIS_COMMENT GENRE → genre = Rock")
    func flacGenreParsed() async throws {
        let url = try writeFixture(named: "genre-rock.flac", base64: Self.flacRockBase64)
        defer { try? FileManager.default.removeItem(at: url.deletingLastPathComponent()) }
        let metadata = try await AudioMetadataParser.parseMetadata(from: url)
        #expect(metadata.genre == "Rock")
    }

    @Test("M4A：iTunes ©gen → genre = Rock")
    func m4aGenreParsed() async throws {
        let url = try writeFixture(named: "genre-rock.m4a", base64: Self.m4aRockBase64)
        defer { try? FileManager.default.removeItem(at: url.deletingLastPathComponent()) }
        let metadata = try await AudioMetadataParser.parseMetadata(from: url)
        #expect(metadata.genre == "Rock")
    }

    @Test("无 genre 标签（mp3/flac/m4a）→ genre = nil")
    func noGenreFilesParseToNil() async throws {
        for (name, base64) in [
            ("smoke-empty.mp3", Self.mp3NoGenreBase64),
            ("smoke-empty.flac", Self.flacNoGenreBase64),
            ("smoke-empty.m4a", Self.m4aNoGenreBase64),
        ] {
            let url = try writeFixture(named: name, base64: base64)
            defer { try? FileManager.default.removeItem(at: url.deletingLastPathComponent()) }
            let metadata = try await AudioMetadataParser.parseMetadata(from: url)
            #expect(metadata.genre == nil, "\(name) 应无 genre")
        }
    }

    // MARK: - normalizedGenre 语义（空/纯空白 → nil，正文去首尾空白）

    @Test("normalizedGenre：nil/空/纯空白 → nil，正文保留")
    func normalizedGenreSemantics() {
        #expect(AudioMetadataParser.normalizedGenre(nil) == nil)
        #expect(AudioMetadataParser.normalizedGenre("") == nil)
        #expect(AudioMetadataParser.normalizedGenre("   ") == nil)
        #expect(AudioMetadataParser.normalizedGenre("Rock") == "Rock")
        #expect(AudioMetadataParser.normalizedGenre("  Rock ") == "Rock")
    }

    // MARK: - Track DB 往返（新库：CREATE 已含 genre 列）

    @Test("Track upsert genre → 读回一致；无 genre → nil")
    func genreSurvivesTrackRoundTrip() throws {
        let dbQueue = try DatabaseQueue()
        let manager = DatabaseManager(dbWriter: dbQueue)
        try manager.createTables()

        try manager.upsertTrack(Track(stableId: "g1", title: "Rock Song", genre: "Rock", path: "/m/r.flac"))
        try manager.upsertTrack(Track(stableId: "g2", title: "No Genre Song", path: "/m/n.flac"))

        try dbQueue.read { db in
            let rock = try Track.filter(Column("stable_id") == "g1").fetchOne(db)
            #expect(rock?.genre == "Rock")
            let none = try Track.filter(Column("stable_id") == "g2").fetchOne(db)
            #expect(none?.genre == nil)
        }
    }

    // MARK: - 老库迁移（track 表无 genre 列 → 补列，幂等）

    /// 老版本建表 DDL（当前 CREATE TABLE track 去掉 genre 列的形态）。
    private static let legacyTrackDDL = """
    CREATE TABLE track (
        id INTEGER PRIMARY KEY,
        stable_id TEXT NOT NULL UNIQUE,
        album_id INTEGER REFERENCES album(id) ON DELETE SET NULL,
        artist_id INTEGER REFERENCES artist(id) ON DELETE SET NULL,
        title TEXT NOT NULL COLLATE NOCASE,
        track_no INTEGER,
        disc_no INTEGER,
        duration_ms INTEGER,
        sample_rate INTEGER,
        bit_depth INTEGER,
        channels INTEGER,
        path TEXT NOT NULL,
        file_size INTEGER,
        modification_date INTEGER,
        replaygain_track_gain REAL,
        replaygain_album_gain REAL,
        replaygain_track_peak REAL,
        replaygain_album_peak REAL,
        has_embedded_art INTEGER DEFAULT 0
    )
    """

    @Test("老库无 genre 列 → 补列成功且幂等 → genre 往返")
    func legacySchemaMigrationAddsGenreColumn() throws {
        let dbQueue = try DatabaseQueue()
        try dbQueue.write { db in
            try db.execute(sql: Self.legacyTrackDDL)
        }
        let manager = DatabaseManager(dbWriter: dbQueue)
        try manager.createTables()  // IF NOT EXISTS：老 track 表保留，其余表/索引照建

        // 迁移：补 genre 列；连调两次验证幂等（列已存在 → 跳过不崩）
        try dbQueue.write { db in
            try DatabaseManager.addTrackGenreColumnIfNeeded(db)
            let columnNames = try db.columns(in: "track").map(\.name)
            #expect(columnNames.contains("genre"))
            try DatabaseManager.addTrackGenreColumnIfNeeded(db)
        }

        try manager.upsertTrack(Track(stableId: "legacy-1", title: "Legacy Genre", genre: "Rock", path: "/m/legacy.flac"))
        let fetched: Track? = try dbQueue.read { db in
            try Track.filter(Column("stable_id") == "legacy-1").fetchOne(db)
        }
        let track = try #require(fetched)
        #expect(track.genre == "Rock")
    }
}
